def guess_journal(*texts):
    for t in texts:
        s = _slugify_name(t)
        if not s:
            continue
        # 先比缩写 slug 表（长键优先，避免 "small" 抢先于 "small-methods"）
        for slug in sorted(JOURNAL_SLUG_HINTS, key=len, reverse=True):
            if slug in s:
                return JOURNAL_SLUG_HINTS[slug]
        for slug, ab in _JOURNAL_SLUGS:
            if slug and slug in s:
                return ab
    return ""


